  document.addEventListener('click', event => {
    const target = event.target.closest('button, a'); if (!target) return;
    if (target.hasAttribute('data-view')) return navigate(target.dataset.view);
    if (target.hasAttribute('data-close-dialog')) return dialog.close();
    if (target.hasAttribute('data-order-filter')) { statusFilter = target.dataset.orderFilter; page = 1; selected.clear(); return render(); }
    const action = target.dataset.action; if (!action) return;
    try {
      if (['order-pay', 'order-fulfill', 'order-cancel', 'order-refund'].includes(action)) { const op = action.replace('order-', ''); const messages = { pay: 'Ghi nhận thanh toán nội bộ, không thu tiền qua cổng thanh toán?', fulfill: 'Đánh dấu đơn đã xử lý? Không tạo vận đơn thật.', cancel: 'Hủy đơn chưa xử lý và hoàn số lượng vào tồn kho?', refund: 'Ghi nhận đã hoàn tiền bên ngoài? Không chuyển tiền tự động.' }; if (!confirm(messages[op])) return; commit(next => S.transitionOrder(next, target.dataset.id, op), 'Đã cập nhật trạng thái đơn hàng'); dialog.close(); orderDetail(target.dataset.id); }
      else if (['menu-up', 'menu-down', 'menu-remove'].includes(action)) { syncMenu(); const i = Number(target.dataset.index); if (action === 'menu-remove') menuDraft.items.splice(i, 1); else { const to = action === 'menu-up' ? i - 1 : i + 1; if (to >= 0 && to < menuDraft.items.length) [menuDraft.items[i], menuDraft.items[to]] = [menuDraft.items[to], menuDraft.items[i]]; } $('#menuItems').innerHTML = menuItemsMarkup(); $('#menuForm').dataset.dirty = 'true'; }
      else actions[action]?.(target);
    } catch (error) { toast(error.message); }
  });
  document.addEventListener('input', event => { const el = event.target; if (el.matches('[data-search=table]')) { query = el.value; page = 1; selected.clear(); render(); $('#tableQuery')?.focus(); } const form = el.closest('#menuForm, #themeForm, #settingsForm'); if (form) form.dataset.dirty = 'true'; if (el.closest('#themeForm')) { clearTimeout(livePreview); livePreview = setTimeout(sendPreview, 100); } if (el.closest('.order-line')) orderEstimate(); });
  document.addEventListener('change', event => { const el = event.target; if (el.matches('[data-filter]')) { const key = el.dataset.filter; if (key === 'status') statusFilter = el.value; if (key === 'stock') stockFilter = el.value; if (key === 'period') period = el.value; if (key === 'sort') sort = el.value; page = 1; selected.clear(); render(); } if (el.matches('[data-select]')) { if (el.checked) selected.add(el.dataset.select); else selected.delete(el.dataset.select); render(); } if (el.matches('[data-select-page]')) { $$('[data-select]', main).forEach(box => { if (el.checked) selected.add(box.dataset.select); else selected.delete(box.dataset.select); }); render(); } });
  function syncMenu() { menuDraft.title = $('[name=menuTitle]', main).value; menuDraft.items = $$('[data-menu-row]', main).map((row, i) => ({ id: menuDraft.items[i]?.id || S.id('link'), label: $('[name=label]', row).value, url: $('[name=url]', row).value })); }
  document.addEventListener('dragstart', event => { const row = event.target.closest('[data-menu-row]'); if (row) { syncMenu(); row.classList.add('is-dragging'); event.dataTransfer.setData('text/plain', row.dataset.menuRow); } });
  document.addEventListener('dragend', event => event.target.closest('[data-menu-row]')?.classList.remove('is-dragging'));
  document.addEventListener('dragover', event => { if (event.target.closest('[data-menu-row]')) event.preventDefault(); });
  document.addEventListener('drop', event => { const row = event.target.closest('[data-menu-row]'); if (!row) return; const from = Number(event.dataTransfer.getData('text/plain')); const to = Number(row.dataset.menuRow); if (Number.isNaN(from) || from === to) return; event.preventDefault(); const [item] = menuDraft.items.splice(from, 1); menuDraft.items.splice(to, 0, item); $('#menuItems').innerHTML = menuItemsMarkup(); $('#menuForm').dataset.dirty = 'true'; });
  $('#mobileMenuButton').onclick = () => setSidebar(!sidebar.classList.contains('is-open')); scrim.onclick = () => setSidebar(false); matchMedia('(max-width:980px)').addEventListener('change', () => setSidebar(false));
  document.addEventListener('keydown', event => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); if (!dialog.open) searchDialog(); } if (event.key === 'Escape' && sidebar.classList.contains('is-open')) setSidebar(false); if (event.key === 'Tab' && sidebar.classList.contains('is-open')) { const list = $$('button, a', sidebar); const first = list[0], last = list.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } });
